import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Plus, 
  Edit, 
  Trash2, 
  Save, 
  X, 
  Search,
  Filter,
  Download,
  Upload,
  Settings,
  Database,
  FileText,
  Award,
  Building,
  Users,
  DollarSign
} from 'lucide-react';
import { 
  getInitiatives, 
  addInitiative,
  updateInitiative, 
  deleteInitiative,
  getAwardPoints,
  addAwardPoint,
  updateAwardPoint,
  deleteAwardPoint,
  getDepartments,
  addDepartment,
  updateDepartment,
  deleteDepartment
} from '../lib/database';
import { formatCurrencyDisplay, parseCurrency } from '../lib/currency';
import { useToast } from '../hooks/use-toast';

const STATUS_OPTIONS = ['مكتملة', 'قيد التنفيذ', 'متأخرة', 'لم تبدأ'];
const PRIORITY_OPTIONS = ['عالية', 'متوسطة', 'منخفضة'];
const POINT_TYPE_OPTIONS = ['نقطة قوة', 'نقطة تحسين'];
const CRITERIA_OPTIONS = [
  'الممكنات',
  'القيادة والحوكمة',
  'الاستراتيجية والتخطيط',
  'العمليات والخدمات',
  'الموارد البشرية',
  'الشراكات والموارد',
  'المعرفة والابتكار',
  'النتائج والأداء',
  'رضا المتعاملين',
  'المسؤولية المجتمعية'
];

const STATUS_COLORS = {
  'مكتملة': 'bg-green-100 text-green-800',
  'قيد التنفيذ': 'bg-yellow-100 text-yellow-800',
  'متأخرة': 'bg-red-100 text-red-800',
  'لم تبدأ': 'bg-gray-100 text-gray-800'
};

const PRIORITY_COLORS = {
  'عالية': 'bg-red-100 text-red-800',
  'متوسطة': 'bg-yellow-100 text-yellow-800',
  'منخفضة': 'bg-green-100 text-green-800'
};

const POINT_TYPE_COLORS = {
  'نقطة قوة': 'bg-green-100 text-green-800',
  'نقطة تحسين': 'bg-yellow-100 text-yellow-800'
};

function ComprehensiveDataManagement({ onDataUpdate, embedded = false }) {
  const { toast } = useToast();
  
  // State for all data
  const [initiatives, setInitiatives] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [departments, setDepartments] = useState([]);
  
  // UI State
  const [activeTab, setActiveTab] = useState('initiatives');
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  
  // Form states
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({});

  useEffect(() => {
    loadAllData();
  }, []);

  const loadAllData = async () => {
    try {
      setIsLoading(true);
      const [initiativesData, awardPointsData, departmentsData] = await Promise.all([
        getInitiatives(),
        getAwardPoints(),
        getDepartments()
      ]);
      setInitiatives(initiativesData);
      setAwardPoints(awardPointsData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  // Initiative Management
  const getInitiativeFormData = () => ({
    name: '',
    description: '',
    department: '',
    responsible_person: '',
    status: 'لم تبدأ',
    priority: 'متوسطة',
    start_date: '',
    end_date: '',
    planned_budget: 0,
    used_budget: 0,
    completion_percentage: 0
  });

  const handleAddInitiative = async () => {
    try {
      const newInitiative = {
        ...formData,
        planned_budget: parseCurrency(formData.planned_budget) || 0,
        used_budget: parseCurrency(formData.used_budget) || 0,
        completion_percentage: parseInt(formData.completion_percentage) || 0
      };
      
      await addInitiative(newInitiative);
      await loadAllData();
      onDataUpdate?.();
      setShowAddForm(false);
      setFormData({});
      toast({
        title: "تم الحفظ",
        description: "تم إضافة المبادرة بنجاح",
      });
    } catch (error) {
      console.error('Error adding initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في إضافة المبادرة",
        variant: "destructive",
      });
    }
  };

  const handleUpdateInitiative = async () => {
    try {
      const updatedInitiative = {
        ...formData,
        planned_budget: parseCurrency(formData.planned_budget) || 0,
        used_budget: parseCurrency(formData.used_budget) || 0,
        completion_percentage: parseInt(formData.completion_percentage) || 0
      };
      
      await updateInitiative(editingId, updatedInitiative);
      await loadAllData();
      onDataUpdate?.();
      setEditingId(null);
      setFormData({});
      toast({
        title: "تم التحديث",
        description: "تم تحديث المبادرة بنجاح",
      });
    } catch (error) {
      console.error('Error updating initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحديث المبادرة",
        variant: "destructive",
      });
    }
  };

  const handleDeleteInitiative = async (id) => {
    if (!confirm('هل أنت متأكد من حذف هذه المبادرة؟')) return;
    
    try {
      await deleteInitiative(id);
      await loadAllData();
      onDataUpdate?.();
      toast({
        title: "تم الحذف",
        description: "تم حذف المبادرة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف المبادرة",
        variant: "destructive",
      });
    }
  };

  // Award Point Management
  const getAwardPointFormData = () => ({
    type: 'نقطة قوة',
    criteria: 'الممكنات',
    criteria_category: 'القدرات التقنية',
    department: '',
    description: '',
    status: 'لم تبدأ',
    responsible_person: ''
  });

  const handleAddAwardPoint = async () => {
    try {
      await addAwardPoint(formData);
      await loadAllData();
      onDataUpdate?.();
      setShowAddForm(false);
      setFormData({});
      toast({
        title: "تم الحفظ",
        description: "تم إضافة نقطة الجائزة بنجاح",
      });
    } catch (error) {
      console.error('Error adding award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في إضافة نقطة الجائزة",
        variant: "destructive",
      });
    }
  };

  const handleUpdateAwardPoint = async () => {
    try {
      await updateAwardPoint(editingId, formData);
      await loadAllData();
      onDataUpdate?.();
      setEditingId(null);
      setFormData({});
      toast({
        title: "تم التحديث",
        description: "تم تحديث نقطة الجائزة بنجاح",
      });
    } catch (error) {
      console.error('Error updating award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحديث نقطة الجائزة",
        variant: "destructive",
      });
    }
  };

  const handleDeleteAwardPoint = async (id) => {
    if (!confirm('هل أنت متأكد من حذف نقطة الجائزة؟')) return;
    
    try {
      await deleteAwardPoint(id);
      await loadAllData();
      onDataUpdate?.();
      toast({
        title: "تم الحذف",
        description: "تم حذف نقطة الجائزة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting award point:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف نقطة الجائزة",
        variant: "destructive",
      });
    }
  };

  // Department Management
  const getDepartmentFormData = () => ({
    name: '',
    manager: '',
    employee_count: 0,
    budget: 0,
    description: ''
  });

  const handleAddDepartment = async () => {
    try {
      const newDepartment = {
        ...formData,
        employee_count: parseInt(formData.employee_count) || 0,
        budget: parseCurrency(formData.budget) || 0
      };
      
      await addDepartment(newDepartment);
      await loadAllData();
      onDataUpdate?.();
      setShowAddForm(false);
      setFormData({});
      toast({
        title: "تم الحفظ",
        description: "تم إضافة الإدارة بنجاح",
      });
    } catch (error) {
      console.error('Error adding department:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في إضافة الإدارة",
        variant: "destructive",
      });
    }
  };

  const handleUpdateDepartment = async () => {
    try {
      const updatedDepartment = {
        ...formData,
        employee_count: parseInt(formData.employee_count) || 0,
        budget: parseCurrency(formData.budget) || 0
      };
      
      await updateDepartment(editingId, updatedDepartment);
      await loadAllData();
      onDataUpdate?.();
      setEditingId(null);
      setFormData({});
      toast({
        title: "تم التحديث",
        description: "تم تحديث الإدارة بنجاح",
      });
    } catch (error) {
      console.error('Error updating department:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحديث الإدارة",
        variant: "destructive",
      });
    }
  };

  const handleDeleteDepartment = async (id) => {
    if (!confirm('هل أنت متأكد من حذف هذه الإدارة؟')) return;
    
    try {
      await deleteDepartment(id);
      await loadAllData();
      onDataUpdate?.();
      toast({
        title: "تم الحذف",
        description: "تم حذف الإدارة بنجاح",
      });
    } catch (error) {
      console.error('Error deleting department:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف الإدارة",
        variant: "destructive",
      });
    }
  };

  // Generic handlers
  const handleEdit = (item, type) => {
    setEditingId(item.id);
    setFormData({ ...item });
    setShowAddForm(true);
  };

  const handleAdd = (type) => {
    setEditingId(null);
    if (type === 'initiatives') {
      setFormData(getInitiativeFormData());
    } else if (type === 'awardPoints') {
      setFormData(getAwardPointFormData());
    } else if (type === 'departments') {
      setFormData(getDepartmentFormData());
    }
    setShowAddForm(true);
  };

  const handleCancel = () => {
    setShowAddForm(false);
    setEditingId(null);
    setFormData({});
  };

  const handleSave = async () => {
    if (activeTab === 'initiatives') {
      if (editingId) {
        await handleUpdateInitiative();
      } else {
        await handleAddInitiative();
      }
    } else if (activeTab === 'awardPoints') {
      if (editingId) {
        await handleUpdateAwardPoint();
      } else {
        await handleAddAwardPoint();
      }
    } else if (activeTab === 'departments') {
      if (editingId) {
        await handleUpdateDepartment();
      } else {
        await handleAddDepartment();
      }
    }
  };

  // Filter data based on search
  const getFilteredData = (data, searchFields) => {
    if (!searchTerm) return data;
    return data.filter(item =>
      searchFields.some(field =>
        item[field]?.toString().toLowerCase().includes(searchTerm.toLowerCase())
      )
    );
  };

  const filteredInitiatives = getFilteredData(initiatives, ['name', 'description', 'department', 'responsible_person']);
  const filteredAwardPoints = getFilteredData(awardPoints, ['type', 'criteria', 'department', 'description', 'responsible_person']);
  const filteredDepartments = getFilteredData(departments, ['name', 'manager', 'description']);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600 mx-auto mb-4"></div>
          <p className="text-gray-600">جاري تحميل البيانات...</p>
        </div>
      </div>
    );
  }

  return (
    <div className={embedded ? "space-y-6" : "space-y-6"}>
      {/* Header */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <Database className="h-5 w-5" />
            إدارة البيانات الشاملة
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between mb-4">
            <div className="relative flex-1 max-w-md">
              <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
              <Input
                placeholder="البحث في البيانات..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10"
              />
            </div>
            <div className="flex gap-2">
              <Button
                onClick={() => handleAdd(activeTab)}
                style={{backgroundColor: 'var(--brand-orange)'}}
                className="text-white"
              >
                <Plus className="h-4 w-4 mr-2" />
                إضافة جديد
              </Button>
            </div>
          </div>

          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="initiatives" className="flex items-center gap-2">
                <FileText className="h-4 w-4" />
                المبادرات ({initiatives.length})
              </TabsTrigger>
              <TabsTrigger value="awardPoints" className="flex items-center gap-2">
                <Award className="h-4 w-4" />
                نقاط الجائزة ({awardPoints.length})
              </TabsTrigger>
              <TabsTrigger value="departments" className="flex items-center gap-2">
                <Building className="h-4 w-4" />
                الإدارات ({departments.length})
              </TabsTrigger>
            </TabsList>

            {/* Initiatives Tab */}
            <TabsContent value="initiatives" className="space-y-4">
              {showAddForm && activeTab === 'initiatives' && (
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">
                      {editingId ? 'تحرير المبادرة' : 'إضافة مبادرة جديدة'}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">اسم المبادرة *</label>
                        <Input
                          value={formData.name || ''}
                          onChange={(e) => setFormData({...formData, name: e.target.value})}
                          placeholder="أدخل اسم المبادرة"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الإدارة *</label>
                        <select
                          value={formData.department || ''}
                          onChange={(e) => setFormData({...formData, department: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          <option value="">اختر الإدارة</option>
                          {departments.map(dept => (
                            <option key={dept.id} value={dept.name}>{dept.name}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">المسؤول *</label>
                        <Input
                          value={formData.responsible_person || ''}
                          onChange={(e) => setFormData({...formData, responsible_person: e.target.value})}
                          placeholder="أدخل اسم المسؤول"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الحالة</label>
                        <select
                          value={formData.status || 'لم تبدأ'}
                          onChange={(e) => setFormData({...formData, status: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          {STATUS_OPTIONS.map(status => (
                            <option key={status} value={status}>{status}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الأولوية</label>
                        <select
                          value={formData.priority || 'متوسطة'}
                          onChange={(e) => setFormData({...formData, priority: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          {PRIORITY_OPTIONS.map(priority => (
                            <option key={priority} value={priority}>{priority}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">نسبة الإكمال (%)</label>
                        <Input
                          type="number"
                          min="0"
                          max="100"
                          value={formData.completion_percentage || 0}
                          onChange={(e) => setFormData({...formData, completion_percentage: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">تاريخ البداية</label>
                        <Input
                          type="date"
                          value={formData.start_date || ''}
                          onChange={(e) => setFormData({...formData, start_date: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">تاريخ النهاية</label>
                        <Input
                          type="date"
                          value={formData.end_date || ''}
                          onChange={(e) => setFormData({...formData, end_date: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الميزانية المخططة (د.إ)</label>
                        <Input
                          type="number"
                          value={formData.planned_budget || 0}
                          onChange={(e) => setFormData({...formData, planned_budget: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الميزانية المستخدمة (د.إ)</label>
                        <Input
                          type="number"
                          value={formData.used_budget || 0}
                          onChange={(e) => setFormData({...formData, used_budget: e.target.value})}
                        />
                      </div>
                      <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">الوصف</label>
                        <Textarea
                          value={formData.description || ''}
                          onChange={(e) => setFormData({...formData, description: e.target.value})}
                          placeholder="أدخل وصف المبادرة"
                          rows={3}
                        />
                      </div>
                    </div>
                    <div className="flex justify-end gap-2 mt-4">
                      <Button variant="outline" onClick={handleCancel}>
                        <X className="h-4 w-4 mr-2" />
                        إلغاء
                      </Button>
                      <Button onClick={handleSave} style={{backgroundColor: 'var(--brand-orange)'}} className="text-white">
                        <Save className="h-4 w-4 mr-2" />
                        حفظ
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              <Card>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="border-b border-gray-200 bg-gray-50">
                          <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                          <th className="text-right p-3 font-medium text-gray-700">اسم المبادرة</th>
                          <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                          <th className="text-right p-3 font-medium text-gray-700">المسؤول</th>
                          <th className="text-center p-3 font-medium text-gray-700">الحالة</th>
                          <th className="text-center p-3 font-medium text-gray-700">نسبة الإكمال</th>
                          <th className="text-center p-3 font-medium text-gray-700">الميزانية</th>
                          <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filteredInitiatives.map((initiative, index) => (
                          <tr key={initiative.id} className="border-b border-gray-100 hover:bg-gray-50">
                            <td className="p-3 text-sm">{index + 1}</td>
                            <td className="p-3">
                              <div className="font-medium text-sm">{initiative.name}</div>
                              {initiative.description && (
                                <div className="text-xs text-gray-500 mt-1 line-clamp-2">
                                  {initiative.description}
                                </div>
                              )}
                            </td>
                            <td className="p-3 text-sm">{initiative.department}</td>
                            <td className="p-3 text-sm">{initiative.responsible_person}</td>
                            <td className="p-3 text-center">
                              <Badge className={`text-xs ${STATUS_COLORS[initiative.status] || 'bg-gray-100 text-gray-800'}`}>
                                {initiative.status}
                              </Badge>
                            </td>
                            <td className="p-3 text-center">
                              <div className="flex items-center justify-center">
                                <div className="w-16 bg-gray-200 rounded-full h-2 mr-2">
                                  <div 
                                    className="bg-blue-600 h-2 rounded-full" 
                                    style={{width: `${initiative.completion_percentage || 0}%`}}
                                  ></div>
                                </div>
                                <span className="text-sm font-medium">{initiative.completion_percentage || 0}%</span>
                              </div>
                            </td>
                            <td className="p-3 text-center text-sm">
                              <div>{formatCurrencyDisplay(initiative.planned_budget || 0)}</div>
                              <div className="text-xs text-gray-500">
                                مستخدم: {formatCurrencyDisplay(initiative.used_budget || 0)}
                              </div>
                            </td>
                            <td className="p-3 text-center">
                              <div className="flex items-center justify-center gap-1">
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleEdit(initiative, 'initiatives')}
                                  className="h-8 w-8 p-0"
                                >
                                  <Edit className="h-3 w-3" />
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleDeleteInitiative(initiative.id)}
                                  className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                                >
                                  <Trash2 className="h-3 w-3" />
                                </Button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {filteredInitiatives.length === 0 && (
                      <div className="text-center py-8">
                        <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                        <p className="text-gray-500">لا توجد مبادرات</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>

            {/* Award Points Tab */}
            <TabsContent value="awardPoints" className="space-y-4">
              {showAddForm && activeTab === 'awardPoints' && (
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">
                      {editingId ? 'تحرير نقطة الجائزة' : 'إضافة نقطة جائزة جديدة'}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">نوع النقطة *</label>
                        <select
                          value={formData.type || 'نقطة قوة'}
                          onChange={(e) => setFormData({...formData, type: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          {POINT_TYPE_OPTIONS.map(type => (
                            <option key={type} value={type}>{type}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">المعيار *</label>
                        <select
                          value={formData.criteria || 'الممكنات'}
                          onChange={(e) => setFormData({...formData, criteria: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          {CRITERIA_OPTIONS.map(criteria => (
                            <option key={criteria} value={criteria}>{criteria}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">تصنيف المعيار</label>
                        <Input
                          value={formData.criteria_category || ''}
                          onChange={(e) => setFormData({...formData, criteria_category: e.target.value})}
                          placeholder="مثل: القدرات التقنية"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الإدارة *</label>
                        <select
                          value={formData.department || ''}
                          onChange={(e) => setFormData({...formData, department: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          <option value="">اختر الإدارة</option>
                          {departments.map(dept => (
                            <option key={dept.id} value={dept.name}>{dept.name}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">المسؤول</label>
                        <Input
                          value={formData.responsible_person || ''}
                          onChange={(e) => setFormData({...formData, responsible_person: e.target.value})}
                          placeholder="أدخل اسم المسؤول"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الحالة</label>
                        <select
                          value={formData.status || 'لم تبدأ'}
                          onChange={(e) => setFormData({...formData, status: e.target.value})}
                          className="w-full p-2 border border-gray-300 rounded-md"
                        >
                          {STATUS_OPTIONS.map(status => (
                            <option key={status} value={status}>{status}</option>
                          ))}
                        </select>
                      </div>
                      <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">الوصف *</label>
                        <Textarea
                          value={formData.description || ''}
                          onChange={(e) => setFormData({...formData, description: e.target.value})}
                          placeholder="أدخل وصف نقطة الجائزة"
                          rows={3}
                        />
                      </div>
                    </div>
                    <div className="flex justify-end gap-2 mt-4">
                      <Button variant="outline" onClick={handleCancel}>
                        <X className="h-4 w-4 mr-2" />
                        إلغاء
                      </Button>
                      <Button onClick={handleSave} style={{backgroundColor: 'var(--brand-orange)'}} className="text-white">
                        <Save className="h-4 w-4 mr-2" />
                        حفظ
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              <Card>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="border-b border-gray-200 bg-gray-50">
                          <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                          <th className="text-center p-3 font-medium text-gray-700">نوع النقطة</th>
                          <th className="text-right p-3 font-medium text-gray-700">المعيار</th>
                          <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                          <th className="text-right p-3 font-medium text-gray-700">الوصف</th>
                          <th className="text-center p-3 font-medium text-gray-700">الحالة</th>
                          <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filteredAwardPoints.map((point, index) => (
                          <tr key={point.id} className="border-b border-gray-100 hover:bg-gray-50">
                            <td className="p-3 text-sm">{index + 1}</td>
                            <td className="p-3 text-center">
                              <Badge className={`text-xs ${POINT_TYPE_COLORS[point.type] || 'bg-gray-100 text-gray-800'}`}>
                                {point.type}
                              </Badge>
                            </td>
                            <td className="p-3 text-sm">
                              <div className="font-medium">{point.criteria}</div>
                              {point.criteria_category && (
                                <div className="text-xs text-gray-500">{point.criteria_category}</div>
                              )}
                            </td>
                            <td className="p-3 text-sm">{point.department}</td>
                            <td className="p-3 text-sm max-w-xs">
                              <div className="line-clamp-2">{point.description}</div>
                            </td>
                            <td className="p-3 text-center">
                              <Badge className={`text-xs ${STATUS_COLORS[point.status] || 'bg-gray-100 text-gray-800'}`}>
                                {point.status}
                              </Badge>
                            </td>
                            <td className="p-3 text-center">
                              <div className="flex items-center justify-center gap-1">
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleEdit(point, 'awardPoints')}
                                  className="h-8 w-8 p-0"
                                >
                                  <Edit className="h-3 w-3" />
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleDeleteAwardPoint(point.id)}
                                  className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                                >
                                  <Trash2 className="h-3 w-3" />
                                </Button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {filteredAwardPoints.length === 0 && (
                      <div className="text-center py-8">
                        <Award className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                        <p className="text-gray-500">لا توجد نقاط جائزة</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>

            {/* Departments Tab */}
            <TabsContent value="departments" className="space-y-4">
              {showAddForm && activeTab === 'departments' && (
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">
                      {editingId ? 'تحرير الإدارة' : 'إضافة إدارة جديدة'}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">اسم الإدارة *</label>
                        <Input
                          value={formData.name || ''}
                          onChange={(e) => setFormData({...formData, name: e.target.value})}
                          placeholder="أدخل اسم الإدارة"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">المدير</label>
                        <Input
                          value={formData.manager || ''}
                          onChange={(e) => setFormData({...formData, manager: e.target.value})}
                          placeholder="أدخل اسم المدير"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">عدد الموظفين</label>
                        <Input
                          type="number"
                          value={formData.employee_count || 0}
                          onChange={(e) => setFormData({...formData, employee_count: e.target.value})}
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">الميزانية (د.إ)</label>
                        <Input
                          type="number"
                          value={formData.budget || 0}
                          onChange={(e) => setFormData({...formData, budget: e.target.value})}
                        />
                      </div>
                      <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">الوصف</label>
                        <Textarea
                          value={formData.description || ''}
                          onChange={(e) => setFormData({...formData, description: e.target.value})}
                          placeholder="أدخل وصف الإدارة"
                          rows={3}
                        />
                      </div>
                    </div>
                    <div className="flex justify-end gap-2 mt-4">
                      <Button variant="outline" onClick={handleCancel}>
                        <X className="h-4 w-4 mr-2" />
                        إلغاء
                      </Button>
                      <Button onClick={handleSave} style={{backgroundColor: 'var(--brand-orange)'}} className="text-white">
                        <Save className="h-4 w-4 mr-2" />
                        حفظ
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              <Card>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="border-b border-gray-200 bg-gray-50">
                          <th className="text-right p-3 font-medium text-gray-700">الرقم</th>
                          <th className="text-right p-3 font-medium text-gray-700">اسم الإدارة</th>
                          <th className="text-right p-3 font-medium text-gray-700">المدير</th>
                          <th className="text-center p-3 font-medium text-gray-700">عدد الموظفين</th>
                          <th className="text-center p-3 font-medium text-gray-700">الميزانية</th>
                          <th className="text-center p-3 font-medium text-gray-700">الإجراءات</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filteredDepartments.map((dept, index) => (
                          <tr key={dept.id} className="border-b border-gray-100 hover:bg-gray-50">
                            <td className="p-3 text-sm">{index + 1}</td>
                            <td className="p-3">
                              <div className="font-medium text-sm">{dept.name}</div>
                              {dept.description && (
                                <div className="text-xs text-gray-500 mt-1 line-clamp-2">
                                  {dept.description}
                                </div>
                              )}
                            </td>
                            <td className="p-3 text-sm">{dept.manager}</td>
                            <td className="p-3 text-center text-sm">{dept.employee_count || 0}</td>
                            <td className="p-3 text-center text-sm">
                              {formatCurrencyDisplay(dept.budget || 0)}
                            </td>
                            <td className="p-3 text-center">
                              <div className="flex items-center justify-center gap-1">
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleEdit(dept, 'departments')}
                                  className="h-8 w-8 p-0"
                                >
                                  <Edit className="h-3 w-3" />
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => handleDeleteDepartment(dept.id)}
                                  className="h-8 w-8 p-0 text-red-600 hover:text-red-700"
                                >
                                  <Trash2 className="h-3 w-3" />
                                </Button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    {filteredDepartments.length === 0 && (
                      <div className="text-center py-8">
                        <Building className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                        <p className="text-gray-500">لا توجد إدارات</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
}

export default ComprehensiveDataManagement;
